<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>11º Torneio Real Manimbu | Resultados</title>
<meta name="description" content="Acompanhe os resultados, confrontos, classificados e artilheiros do 11º Torneio Real Manimbu.">
<style>
:root{--red:#d71920;--red2:#8d080e;--gold:#e7bd61;--ink:#09090b;--panel:#151518;--muted:#aaa;--line:#343438}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% -10%,#3a090c 0,#111 38%,#080809 78%);color:#f7f4ee;font-family:Arial,Helvetica,sans-serif}
a{color:inherit}.wrap{max-width:1160px;margin:auto;padding:0 20px}
header{padding:30px 0 20px;text-align:center;border-bottom:1px solid #4b2924;background:linear-gradient(180deg,#080808eF,#0c0b0b99)}
.crest{width:116px;height:116px;object-fit:cover;border-radius:50%;border:2px solid var(--gold);box-shadow:0 0 30px #c18b3b55}
.eyebrow{color:var(--gold);font-size:12px;letter-spacing:4px;text-transform:uppercase;margin:15px 0 7px}
h1{font-size:clamp(28px,5vw,52px);font-weight:900;font-style:italic;text-transform:uppercase;margin:0;text-shadow:0 3px 0 #6b080d}
header p{color:#d7c9c3;margin:12px 0 0}.tribute{color:var(--gold);font-size:13px;margin-top:8px}
main{padding:28px 0 60px}.section-title{display:flex;align-items:center;gap:12px;margin:0 0 17px;font-size:20px;text-transform:uppercase}.section-title:before{content:"";width:5px;height:24px;background:var(--red);border-radius:5px}
.tabs{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:22px}
.tab{border:1px solid #5b292c;background:#171416;color:#eee;padding:15px 8px;border-radius:12px;font-weight:900;cursor:pointer;transition:.2s}.tab small{display:block;color:#bd9a9a;font-size:11px;margin-top:4px}.tab.active,.tab:hover{background:linear-gradient(135deg,#e51b24,#79090f);border-color:#f05b5f;box-shadow:0 8px 25px #9e101d44}
.top-grid{display:grid;grid-template-columns:1.4fr 1fr;gap:16px;margin-bottom:24px}
.panel{background:linear-gradient(145deg,#1a191b,#101012);border:1px solid #393336;border-radius:16px;padding:20px;box-shadow:0 12px 30px #0005}
.panel h3{margin:0 0 14px;font-size:14px;letter-spacing:1.5px;text-transform:uppercase;color:var(--gold)}
.scorer{display:flex;align-items:center;gap:15px}.scorer .ball{width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:#3b1115;border:1px solid var(--gold);font-size:23px}.scorer strong{display:block;font-size:18px}.scorer span{color:var(--muted);font-size:13px}
.champ{color:var(--gold);font-weight:bold;font-size:18px}
.match-list{display:grid;gap:10px}.match{background:#0c0c0e;border:1px solid #333;border-radius:12px;padding:13px 14px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:10px}.team{font-weight:700;font-size:14px}.team:last-child{text-align:right}.score{display:flex;align-items:center;gap:8px;font-weight:900;font-size:20px}.score em{font-style:normal;color:#777;font-size:12px}.meta{grid-column:1/-1;display:flex;justify-content:space-between;color:#888;font-size:11px;border-top:1px solid #29292c;padding-top:8px;margin-top:2px}.winner{color:#f3cb72}.stage{color:#f36a6e;font-weight:bold}
.empty{padding:24px;text-align:center;color:#999;border:1px dashed #464044;border-radius:12px}
.qualified{display:flex;flex-wrap:wrap;gap:8px}.pill{background:#2a1719;border:1px solid #73343a;color:#f3d4d4;border-radius:30px;padding:8px 12px;font-size:13px}
.notice{margin-top:20px;color:#777;font-size:12px;text-align:center}
footer{border-top:1px solid #38292b;padding:22px;text-align:center;color:#8f8585;font-size:12px}
#adminOpen{position:fixed;right:16px;bottom:16px;background:#171416;color:#d9c18d;border:1px solid #765b34;border-radius:50px;padding:12px 17px;cursor:pointer;z-index:4}
.modal{position:fixed;inset:0;background:#000c;display:none;align-items:center;justify-content:center;padding:15px;z-index:10;overflow:auto}.modal.show{display:flex}.modalbox{background:#141316;border:1px solid #6d3438;border-radius:16px;padding:22px;width:min(900px,100%);max-height:94vh;overflow:auto}.modalhead{display:flex;justify-content:space-between;align-items:center;gap:12px}.modalhead h2{margin:0;color:var(--gold)}.close{background:none;color:white;border:0;font-size:26px;cursor:pointer}
input,select,textarea{width:100%;background:#09090b;color:#eee;border:1px solid #494247;border-radius:8px;padding:11px;margin:5px 0 12px;font:inherit}label{font-size:12px;color:#c7b8b8}textarea{min-height:90px;resize:vertical}.btn{border:0;border-radius:8px;padding:11px 16px;background:var(--red);color:white;font-weight:bold;cursor:pointer}.btn.secondary{background:#393338}.btn.gold{background:#9b722e}.btnrow{display:flex;gap:8px;flex-wrap:wrap}.admin-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.admin-match{border:1px solid #3a3337;border-radius:10px;padding:12px;margin:10px 0}.admin-match h4{margin:0 0 8px;color:var(--gold)}.tiny{font-size:11px;color:#999}.hidden{display:none!important}
@media(max-width:650px){.tabs{grid-template-columns:repeat(2,1fr)}.top-grid{grid-template-columns:1fr}.match{grid-template-columns:1fr auto 1fr;padding:11px 9px}.team{font-size:12px}.score{font-size:17px}.admin-grid{grid-template-columns:1fr}.panel{padding:15px}}
</style></head><body>
<header><div class="wrap"><img class="crest" src="assets/brasao-real-manimbu.jpg" alt="Brasão Real Manimbu"><div class="eyebrow">11 anos de história</div><h1>11º Torneio<br>Real Manimbu</h1><p>Resultados oficiais • Confrontos • Classificação</p><div class="tribute">Uma homenagem especial a Tatar, criadora do Real Manimbu</div></div></header>
<main class="wrap">
<h2 class="section-title">Escolha sua categoria</h2><div class="tabs" id="tabs"></div>
<div class="top-grid"><section class="panel"><h3>Artilheiro da categoria</h3><div id="scorer" class="scorer"><div class="ball">⚽</div><div><strong>A definir</strong><span>Artilheiro será atualizado em breve</span></div></div></section>
<section class="panel"><h3>Campeão da categoria</h3><div id="champion" class="champ">Em disputa</div><p class="tiny">Acompanhe aqui quem levantar a taça.</p></section></div>
<section class="panel" style="margin-bottom:18px"><h3>Classificados para a próxima fase</h3><div id="qualified" class="qualified"><span class="tiny">Classificados ainda não divulgados.</span></div></section>
<h2 class="section-title">Tabela de jogos e resultados</h2><div id="matches" class="match-list"></div>
<div class="notice">Os resultados e classificados são atualizados pela organização do torneio.</div>
</main><footer>REAL MANIMBU • ESPORTE, UNIÃO E MUITA EMOÇÃO</footer>
<button id="adminOpen">⚙ Área do administrador</button>
<div class="modal" id="modal"><div class="modalbox"><div class="modalhead"><h2>Área do administrador</h2><button class="close" id="close">×</button></div>
<div id="loginView"><p class="tiny">Entre para atualizar jogos, equipes, classificados e artilheiros.</p><label>Usuário</label><input id="user" value="admin"><label>Senha</label><input id="pass" type="password" placeholder="Digite a senha"><button class="btn" id="login">Entrar</button><p id="loginError" class="tiny"></p></div>
<div id="adminView" class="hidden">
<div class="btnrow"><button class="btn secondary" id="logout">Sair</button><button class="btn gold" id="saveAll">Salvar alterações</button></div>
<label>Categoria que deseja editar</label><select id="adminCategory"></select>
<div id="adminEditor"></div>
</div></div></div>
<script>
let state=null, active='10-11', logged=false;
const $=s=>document.querySelector(s);
async function api(action,body){let r=await fetch('api.php?action='+action,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||'Erro');return j}
function cat(){return state.categories.find(c=>c.id===active)||state.categories[0]}
function renderTabs(){ $('#tabs').innerHTML=state.categories.map(c=>`<button class="tab ${c.id===active?'active':''}" data-id="${c.id}">${c.label}<small>Ver jogos e resultados</small></button>`).join('');document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{active=b.dataset.id;render()})}
function render(){renderTabs();let c=cat();let s=c.scorer||{};$('#scorer').innerHTML=s.name?`<div class="ball">⚽</div><div><strong>${esc(s.name)}</strong><span>${esc(s.team||'Equipe não informada')} • ${Number(s.goals)||0} gols</span></div>`:`<div class="ball">⚽</div><div><strong>A definir</strong><span>Artilheiro será atualizado em breve</span></div>`;
$('#champion').textContent=c.champion||'Em disputa';$('#qualified').innerHTML=(c.qualified||[]).length?c.qualified.map(t=>`<span class="pill">${esc(t)}</span>`).join(''):'<span class="tiny">Classificados ainda não divulgados.</span>';
$('#matches').innerHTML=c.matches.length?c.matches.map(m=>`<article class="match"><div class="team ${m.winner===m.home&&m.winner?'winner':''}">${esc(m.home||'A definir')}</div><div class="score">${m.home_score!==''?esc(m.home_score):'–'} <em>X</em> ${m.away_score!==''?esc(m.away_score):'–'}</div><div class="team ${m.winner===m.away&&m.winner?'winner':''}">${esc(m.away||'A definir')}</div><div class="meta"><span class="stage">${esc(m.stage||'Confronto')}</span><span>${[m.date,m.time,m.location].filter(Boolean).map(esc).join(' • ')||'Data a definir'}</span></div></article>`).join(''):'<div class="empty">Nenhum confronto cadastrado.</div>';
if(logged)renderAdmin()}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$('#adminOpen').onclick=()=>{$('#modal').classList.add('show')};$('#close').onclick=()=>$('#modal').classList.remove('show');
$('#modal').onclick=e=>{if(e.target.id==='modal')$('#modal').classList.remove('show')};
$('#login').onclick=async()=>{try{await api('login',{user:$('#user').value,password:$('#pass').value});logged=true;$('#loginView').classList.add('hidden');$('#adminView').classList.remove('hidden');renderAdmin()}catch(e){$('#loginError').textContent=e.message}};
$('#logout').onclick=async()=>{await api('logout');logged=false;$('#adminView').classList.add('hidden');$('#loginView').classList.remove('hidden')};
$('#adminCategory').onchange=()=>{active=$('#adminCategory').value;renderTabs();renderAdmin()};
function renderAdmin(){let sel=$('#adminCategory');if(![...sel.options].some(o=>o.value===active)){sel.innerHTML=state.categories.map(c=>`<option value="${c.id}">${c.label}</option>`).join('')}sel.value=active;let c=cat();
$('#adminEditor').innerHTML=`
<h3>Equipes cadastradas</h3><label>Uma equipe por linha (edite os nomes ou acrescente novas equipes)</label><textarea id="teams">${esc(c.teams.join('\n'))}</textarea>
<h3>Confrontos e resultados</h3><p class="tiny">Cadastre o placar e selecione manualmente o vencedor. Você pode adicionar jogos de qualquer fase, sem depender de chaveamento automático.</p>
<div id="adminMatches">${c.matches.map((m,i)=>matchForm(m,i,c.teams)).join('')}</div>
<div class="btnrow"><button class="btn secondary" id="addMatch">+ Adicionar confronto</button></div>
<h3>Classificados para a próxima fase</h3><label>Digite ou cole os nomes, um por linha. A organização define manualmente quem avança.</label><textarea id="qualifiedInput">${esc((c.qualified||[]).join('\n'))}</textarea>
<div class="admin-grid"><div><h3>Artilheiro</h3><label>Nome do jogador</label><input id="scorerName" value="${esc(c.scorer?.name||'')}"><label>Equipe</label><input id="scorerTeam" value="${esc(c.scorer?.team||'')}"><label>Gols</label><input id="scorerGoals" type="number" min="0" value="${Number(c.scorer?.goals)||0}"></div><div><h3>Campeão</h3><label>Nome da equipe campeã</label><input id="championInput" value="${esc(c.champion||'')}"><h3>Nome da categoria</h3><label>Rótulo exibido no site</label><input id="labelInput" value="${esc(c.label)}"></div></div>
<p class="tiny">Atenção: as alterações ficam pendentes até clicar em “Salvar alterações”.</p>`;
document.querySelectorAll('.winnerSelect').forEach((el,i)=>el.onchange=()=>{});
$('#addMatch').onclick=()=>{let c=cat();c.matches.push({id:c.id+'-'+Date.now(),stage:'Próxima fase',home:'',away:'',home_score:'',away_score:'',winner:'',date:'',time:'',location:''});renderAdmin()};
}
function matchForm(m,i,teams){let opts=['',...teams].map(t=>`<option ${m.winner===t?'selected':''} value="${esc(t)}">${esc(t||'Sem vencedor definido')}</option>`).join('');
return `<div class="admin-match" data-index="${i}"><h4>Jogo ${i+1}</h4><div class="admin-grid"><div><label>Equipe A</label><input data-field="home" value="${esc(m.home)}"></div><div><label>Equipe B</label><input data-field="away" value="${esc(m.away)}"></div><div><label>Gols equipe A</label><input data-field="home_score" value="${esc(m.home_score)}"></div><div><label>Gols equipe B</label><input data-field="away_score" value="${esc(m.away_score)}"></div><div><label>Vencedor (seleção manual)</label><select data-field="winner">${opts}</select></div><div><label>Fase</label><input data-field="stage" value="${esc(m.stage)}"></div><div><label>Data</label><input data-field="date" placeholder="Ex.: 22/11/2026" value="${esc(m.date)}"></div><div><label>Horário</label><input data-field="time" placeholder="Ex.: 08:00" value="${esc(m.time)}"></div><div style="grid-column:1/-1"><label>Local</label><input data-field="location" value="${esc(m.location)}"></div></div><button class="btn secondary removeMatch" type="button">Excluir confronto</button></div>`}
$('#saveAll').onclick=async()=>{try{let c=cat();c.teams=$('#teams').value.split('\n').map(x=>x.trim()).filter(Boolean);document.querySelectorAll('.admin-match').forEach(el=>{let i=Number(el.dataset.index),m=c.matches[i];el.querySelectorAll('[data-field]').forEach(x=>m[x.dataset.field]=x.value.trim())});c.qualified=$('#qualifiedInput').value.split('\n').map(x=>x.trim()).filter(Boolean);c.scorer={name:$('#scorerName').value.trim(),team:$('#scorerTeam').value.trim(),goals:Number($('#scorerGoals').value)||0};c.champion=$('#championInput').value.trim();c.label=$('#labelInput').value.trim()||c.label;
await api('save',{data:state});alert('Alterações salvas com sucesso!');render()}catch(e){alert(e.message)}};
document.addEventListener('click',e=>{if(e.target.classList.contains('removeMatch')){let i=Number(e.target.closest('.admin-match').dataset.index);cat().matches.splice(i,1);renderAdmin()}});
(async()=>{try{let r=await api('data');state=r.data;logged=r.logged;if(logged){$('#loginView').classList.add('hidden');$('#adminView').classList.remove('hidden')}render()}catch(e){$('#matches').innerHTML='<div class="empty">Não foi possível carregar os dados.</div>'}})();
</script></body></html>